// Package api's real consumer of these modules is api.gen.go, which is NOT
// tracked (it is regenerated by `make api` at image build, container start,
// and in CI). Without a tracked import, `go mod tidy` run before generation —
// which is exactly what Dependabot's updater does, and what a fresh clone
// might do — silently drops the requires from go.mod, and the build only
// breaks after the next generation. This file pins them to tracked source.
// Keep it in sync with the generated file's third-party imports.
package api

import (
	_ "github.com/getkin/kin-openapi/openapi3"
	_ "github.com/gin-gonic/gin"
	_ "github.com/oapi-codegen/runtime"
	_ "github.com/oapi-codegen/runtime/strictmiddleware/gin"
	_ "github.com/oapi-codegen/runtime/types"
)
